$pdo=Database::getConnection();$service=new ChantierFinancialComplianceService($pdo);$audit=$service->auditActive();
$rows=$pdo->query("SELECT c.code,c.titre,c.financial_data_status,c.financial_data_checked_at,c.financial_data_issue,d.numero_devis,d.total_ttc,cl.nom_client FROM chantier_banamur c LEFT JOIN devis_banamur d ON d.id=c.devis_id LEFT JOIN client_banamur cl ON cl.id_client=c.client_id WHERE c.archived_at IS NULL ORDER BY (c.financial_data_status='compliant'),c.code,c.id")->fetchAll(PDO::FETCH_ASSOC)?:[];
$issues=[];foreach($rows as $row)foreach(array_filter(array_map('trim',explode('|',(string)$row['financial_data_issue']))) as $issue)$issues[$issue]=($issues[$issue]??0)+1;arsort($issues);
$rate=$audit['total']?round($audit['compliant']/$audit['total']*100,1):100;$dominant=$issues?array_key_first($issues):'Aucune anomalie';$dominantCount=$issues?(int)reset($issues):0;
$analysis=$audit['incomplete']===0?'Les dossiers actifs sont complets. Les indicateurs financiers et prévisionnels disposent d’un niveau documentaire satisfaisant.':'Les '.$audit['total'].' chantiers actifs restent intégralement inclus dans les statistiques. '.$audit['incomplete'].' dossier(s) présentent toutefois des informations à compléter. Le point le plus fréquent est « '.$dominant.' » ('.$dominantCount.' chantier(s)). Priorité recommandée : fiabiliser les devis et leurs montants, puis les plannings, les déboursés et enfin les échéanciers d’encaissement.';
$format=strtolower((string)($_GET['format']??'xlsx'));$clear=static function():void{while(ob_get_level()>0)ob_end_clean();};

if($format==='xlsx'){
 $book=new Spreadsheet();$book->getProperties()->setCreator('FINEA')->setTitle('Fiabilité des chantiers actifs')->setSubject('Rapport de régularisation');$sheet=$book->getActiveSheet();$sheet->setTitle('Synthèse DG');$navy='1D2B57';$yellow='FABD02';
 $sheet->mergeCells('A1:H2')->setCellValue('A1','FINEA · RAPPORT DE FIABILITÉ DES CHANTIERS ACTIFS');$sheet->getStyle('A1:H2')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($navy);$sheet->getStyle('A1:H2')->getFont()->setBold(true)->setSize(18)->getColor()->setRGB('FFFFFF');$sheet->getStyle('A1:H2')->getAlignment()->setVertical(Alignment::VERTICAL_CENTER);
 $sheet->mergeCells('A3:H3')->setCellValue('A3','Édité le '.date('d/m/Y à H:i').' · Les dossiers incomplets restent inclus dans les statistiques.');$sheet->getStyle('A3:H3')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($yellow);$sheet->getStyle('A3:H3')->getFont()->setBold(true);
 $kpis=[['Chantiers actifs',$audit['total'],'F8FAFC'],['Conformes',$audit['compliant'],'DCFCE7'],['À régulariser',$audit['incomplete'],'FEF3C7'],['Fiabilité',$rate.' %',$rate>=80?'DCFCE7':($rate>=50?'FEF3C7':'FEE2E2')]];foreach($kpis as $i=>$k){$start=chr(65+$i*2);$end=chr(66+$i*2);$sheet->mergeCells($start.'5:'.$end.'5')->setCellValue($start.'5',$k[0]);$sheet->mergeCells($start.'6:'.$end.'7')->setCellValue($start.'6',$k[1]);$sheet->getStyle($start.'5:'.$end.'7')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($k[2]);$sheet->getStyle($start.'5:'.$end.'7')->getAlignment()->setHorizontal(Alignment::HORIZONTAL_CENTER)->setVertical(Alignment::VERTICAL_CENTER);$sheet->getStyle($start.'6')->getFont()->setBold(true)->setSize(20)->getColor()->setRGB($navy);}
 $sheet->mergeCells('A9:H9')->setCellValue('A9','ANALYSE DE DIRECTION');$sheet->getStyle('A9:H9')->getFont()->setBold(true)->getColor()->setRGB($navy);$sheet->mergeCells('A10:H13')->setCellValue('A10',$analysis);$sheet->getStyle('A10:H13')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('F8FAFC');$sheet->getStyle('A10:H13')->getAlignment()->setWrapText(true)->setVertical(Alignment::VERTICAL_CENTER);$sheet->getStyle('A10:H13')->getBorders()->getOutline()->setBorderStyle(Border::BORDER_THIN)->getColor()->setRGB('DFE6F1');
 $sheet->setCellValue('A15','Anomalie')->setCellValue('B15','Chantiers');$sheet->getStyle('A15:B15')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($navy);$sheet->getStyle('A15:B15')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$line=16;foreach($issues as $issue=>$count){$sheet->setCellValue('A'.$line,$issue)->setCellValue('B'.$line,$count);$line++;}if($line===16){$sheet->setCellValue('A16','Aucune anomalie')->setCellValue('B16',0);$line=17;}
 $category=new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_STRING,"'Synthèse DG'!\$A\$16:\$A\$".($line-1),null,$line-16);$values=new DataSeriesValues(DataSeriesValues::DATASERIES_TYPE_NUMBER,"'Synthèse DG'!\$B\$16:\$B\$".($line-1),null,$line-16);$series=new DataSeries(DataSeries::TYPE_BARCHART,DataSeries::GROUPING_CLUSTERED,[0],[],[$category],[$values]);$series->setPlotDirection(DataSeries::DIRECTION_BAR);$chart=new Chart('anomaly_chart',new Title('Anomalies par catégorie'),new Legend(Legend::POSITION_BOTTOM),new PlotArea(null,[$series]));$chart->setTopLeftPosition('D15')->setBottomRightPosition('H31');$sheet->addChart($chart);$sheet->getColumnDimension('A')->setWidth(62);foreach(['B','C','D','E','F','G','H'] as $c)$sheet->getColumnDimension($c)->setWidth(18);$sheet->getSheetView()->setShowGridlines(false);
 $detail=$book->createSheet();$detail->setTitle('Détail par chantier');$headers=['Code','Chantier','Client','Devis','Montant TTC FCFA','Statut','Corrections attendues','Contrôlé le'];$detail->fromArray($headers,null,'A1');$detail->getStyle('A1:H1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($navy);$detail->getStyle('A1:H1')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$r=2;foreach($rows as $row){$detail->fromArray([$row['code'],$row['titre'],$row['nom_client'],$row['numero_devis'],(float)$row['total_ttc'],$row['financial_data_status']==='compliant'?'Conforme':'À régulariser',str_replace(' | ',"\n",(string)$row['financial_data_issue']),$row['financial_data_checked_at']],null,'A'.$r);$detail->getStyle('A'.$r.':H'.$r)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($row['financial_data_status']==='compliant'?'F0FDF4':($r%2?'FFFBEB':'FFFFFF'));$r++;}$detail->freezePane('A2');$detail->setAutoFilter('A1:H'.max(1,$r-1));$detail->getStyle('A1:H'.max(1,$r-1))->getAlignment()->setWrapText(true)->setVertical(Alignment::VERTICAL_TOP);$detail->getStyle('E2:E'.max(2,$r-1))->getNumberFormat()->setFormatCode('#,##0 "FCFA"');foreach(['A'=>15,'B'=>35,'C'=>28,'D'=>22,'E'=>20,'F'=>18,'G'=>72,'H'=>22] as $c=>$w)$detail->getColumnDimension($c)->setWidth($w);
 $rules=$book->createSheet();$rules->setTitle('Référentiel');$rules->fromArray([['Bloc','Règle attendue','Pourquoi cette donnée compte'],['Devis','Rattaché, avec lignes et montant TTC supérieur à zéro.','Base du contrat, du chiffre d’affaires et de la marge.'],['Déboursé','Lié au devis, planifié et limité à 65 % du TTC.','Base du coût et de la marge prévisionnelle.'],['Planning','Dates du devis et des travaux cohérentes.','Positionnement des prévisions de dépenses.'],['Facturation','Dates et pourcentages couvrant 100 % du devis.','Projection des encaissements et de la trésorerie.']],null,'A1');$rules->getStyle('A1:C1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB($navy);$rules->getStyle('A1:C1')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$rules->getStyle('A1:C5')->getAlignment()->setWrapText(true)->setVertical(Alignment::VERTICAL_TOP);$rules->getColumnDimension('A')->setWidth(22);$rules->getColumnDimension('B')->setWidth(62);$rules->getColumnDimension('C')->setWidth(62);$book->setActiveSheetIndex(0);
 $clear();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="rapport_finea_regularisation_'.date('Ymd_His').'.xlsx"');header('Cache-Control:max-age=0');$writer=new Xlsx($book);$writer->setIncludeCharts(true);$writer->save('php://output');exit;
}

if($format!=='pdf')throw new DomainException('Format non pris en charge.');
class RegularisationPdf extends TCPDF{public function Header():void{$this->SetFillColor(29,43,87);$this->Rect(0,0,$this->getPageWidth(),25,'F');$this->SetXY(12,7);$this->SetTextColor(255,255,255);$this->SetFont('dejavusans','B',15);$this->Cell(0,6,'FINEA · FIABILITÉ DES CHANTIERS ACTIFS');$this->SetFillColor(250,189,2);$this->Rect(12,23,44,2,'F');}public function Footer():void{$this->SetY(-12);$this->SetTextColor(100,116,139);$this->SetFont('dejavusans','',7);$this->Cell(0,5,'FINEA · Rapport de régularisation · Page '.$this->getAliasNumPage().'/'.$this->getAliasNbPages(),0,0,'C');}}
$pdf=new RegularisationPdf('L','mm','A4',true,'UTF-8',false);$pdf->SetCreator('FINEA');$pdf->SetTitle('Rapport de fiabilité des chantiers');$pdf->SetMargins(12,31,12);$pdf->SetAutoPageBreak(true,15);$pdf->AddPage();$pdf->SetFont('dejavusans','',9);$html='<table cellpadding="7"><tr><td bgcolor="#f8fafc"><b>Chantiers actifs</b><br><font size="18">'.$audit['total'].'</font></td><td bgcolor="#dcfce7"><b>Conformes</b><br><font size="18">'.$audit['compliant'].'</font></td><td bgcolor="#fef3c7"><b>À régulariser</b><br><font size="18">'.$audit['incomplete'].'</font></td><td bgcolor="#e0e7ff"><b>Fiabilité</b><br><font size="18">'.number_format($rate,1,',',' ').' %</font></td></tr></table><br><h2 color="#1d2b57">Lecture de direction</h2><p>'.$analysis.'</p><h2 color="#1d2b57">Répartition des anomalies</h2><table cellpadding="5" border="1"><tr bgcolor="#fabd02" color="#000000"><th width="80%"><b>Anomalie</b></th><th width="20%"><b>Chantiers</b></th></tr>';foreach($issues as $issue=>$count)$html.='<tr><td>'.htmlspecialchars($issue).'</td><td>'.$count.'</td></tr>';$html.='</table>';$pdf->writeHTML($html,true,false,true,false,'');$pdf->AddPage();$html='<h2 color="#1d2b57">Analyse chantier par chantier</h2><table cellpadding="4" border="1"><tr bgcolor="#fabd02" color="#000000"><th width="10%"><b>Code</b></th><th width="20%"><b>Chantier / client</b></th><th width="15%"><b>Devis</b></th><th width="13%"><b>Montant TTC</b></th><th width="12%"><b>Statut</b></th><th width="30%"><b>Corrections attendues</b></th></tr>';foreach($rows as $row){$html.='<tr><td>'.htmlspecialchars((string)$row['code']).'</td><td>'.htmlspecialchars((string)$row['titre']).'<br><small>'.htmlspecialchars((string)$row['nom_client']).'</small></td><td>'.htmlspecialchars((string)$row['numero_devis']).'</td><td>'.number_format((float)$row['total_ttc'],0,',',' ').' FCFA</td><td>'.($row['financial_data_status']==='compliant'?'Conforme':'À régulariser').'</td><td>'.htmlspecialchars(str_replace(' | ',' · ',(string)$row['financial_data_issue'])).'</td></tr>';}$html.='</table>';$pdf->writeHTML($html,true,false,true,false,'');$clear();$pdf->Output('rapport_finea_regularisation_'.date('Ymd_His').'.pdf','D');exit;
